// Local search treats Arabic spelling/diacritics and Latin accents consistently.
export function normalizeSearch(value=''){return String(value).normalize('NFKD').replace(/[\u0300-\u036f\u0610-\u061a\u064b-\u065f\u0670\u0640]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-0x660)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-0x6f0)).toLocaleLowerCase().replace(/\s+/g,' ').trim();}
export function searchDocument(document,query){const terms=normalizeSearch(query).split(' ').filter(Boolean);if(!terms.length)return{matched:true,page:null,snippet:''};const metadata=normalizeSearch([document.name,document.folder,...document.tags||[]].join(' '));const texts=document.pages.map(page=>normalizeSearch(page.ocr?.text||''));if(!terms.every(term=>metadata.includes(term)||texts.some(text=>text.includes(term))))return{matched:false};const index=texts.findIndex(text=>terms.some(term=>text.includes(term)));if(index<0)return{matched:true,page:null,snippet:''};const text=document.pages[index].ocr.text.replace(/\s+/g,' '),position=texts[index].indexOf(terms.find(term=>texts[index].includes(term)));const start=Math.max(0,position-35);return{matched:true,page:document.pages[index].id,pageNumber:index+1,snippet:(start?'…':'')+text.slice(start,start+150)+(text.length>start+150?'…':'')};}
export function formatBytes(bytes,locale='ar'){if(!Number.isFinite(bytes)||bytes<0)return '—';const units=['B','KB','MB','GB'];let n=bytes,i=0;while(n>=1024&&i<3){n/=1024;i++;}return new Intl.NumberFormat(locale,{maximumFractionDigits:i?1:0}).format(n)+' '+units[i];}
export function documentBytes(documents){const seen=new Set();let bytes=0;for(const document of documents)for(const page of document.pages)for(const blob of [page.blob,page.original,...(page.history||[]).map(s=>s.blob),...(page.redo||[]).map(s=>s.blob)])if(blob instanceof Blob&&!seen.has(blob)){seen.add(blob);bytes+=blob.size;}return bytes;}
